(()=>{const r={physical:23,emotional:28,intellectual:33};function c(o,t,e){const n=Math.abs(t-o),i=Math.ceil(n/(1e3*60*60*24));return Math.sin(2*Math.PI*i/e)*100}function p(o,t){return{physical:c(o,t,r.physical),emotional:c(o,t,r.emotional),intellectual:c(o,t,r.intellectual)}}let u=null;function m(o){const t=document.getElementById("bio-canvas");if(!t)return;if(!window.Chart){console.error("Chart.js is not loaded.");return}const e=new Date;e.setHours(0,0,0,0);const n=[],i=[],l=[],h=[];for(let a=-7;a<=14;a++){const s=new Date(e);s.setDate(e.getDate()+a),n.push(`${s.getDate()}.${s.getMonth()+1}.`);const d=p(o,s);i.push(d.physical),l.push(d.emotional),h.push(d.intellectual)}const v={type:"line",data:{labels:n,datasets:[{label:"Fyzick\xFD (23 dn\u016F)",data:i,borderColor:"#ff4b4b",backgroundColor:"rgba(255, 75, 75, 0.1)",borderWidth:2,tension:.4,fill:!0,pointRadius:0,pointHoverRadius:6},{label:"Emo\u010Dn\xED (28 dn\u016F)",data:l,borderColor:"#4caf50",backgroundColor:"rgba(76, 175, 80, 0.1)",borderWidth:2,tension:.4,fill:!0,pointRadius:0,pointHoverRadius:6},{label:"Intelektu\xE1ln\xED (33 dn\u016F)",data:h,borderColor:"#00bcd4",backgroundColor:"rgba(0, 188, 212, 0.1)",borderWidth:2,tension:.4,fill:!0,pointRadius:0,pointHoverRadius:6}]},options:{responsive:!0,maintainAspectRatio:!1,interaction:{mode:"index",intersect:!1},plugins:{legend:{display:!1},tooltip:{backgroundColor:"rgba(10, 10, 26, 0.9)",titleColor:"#D4AF37",bodyColor:"#e0e0e0",borderColor:"rgba(212, 175, 55, 0.2)",borderWidth:1,padding:10,displayColors:!0,callbacks:{label:function(a){return`${a.dataset.label}: ${Math.round(a.raw)}%`}}}},scales:{x:{grid:{color:"rgba(255, 255, 255, 0.05)",drawBorder:!1},ticks:{color:"#a0a0b0",maxTicksLimit:10}},y:{min:-100,max:100,grid:{color:a=>a.tick.value===0?"rgba(255, 255, 255, 0.2)":"rgba(255, 255, 255, 0.05)",drawBorder:!1},ticks:{color:"#a0a0b0",stepSize:50,callback:function(a){return a+"%"}}}}}};u&&u.destroy(),u=new Chart(t,v),y(o)}function b(o,t){const e=t>=80?"bl\xEDzko horn\xEDho bodu":t>=25?"v kladn\xE9 \u010D\xE1sti":t>-25?"bl\xEDzko nulov\xE9 osy":t>-80?"v z\xE1porn\xE9 \u010D\xE1sti":"bl\xEDzko doln\xEDho bodu";return`${{physical:"Fyzick\xE1",emotional:"Emo\u010Dn\xED",intellectual:"Intelektu\xE1ln\xED"}[o]||"Modelov\xE1"} k\u0159ivka je ${e}. Jde o matematick\xFD model z data narozen\xED, ne m\u011B\u0159en\xED dne\u0161n\xED kondice, n\xE1lady nebo soust\u0159ed\u011Bn\xED.`}function y(o){const t=p(o,new Date),e=document.getElementById("bio-stats-container");e&&(e.innerHTML=`
        <div class="bio-stat-card">
            <div class="bio-stat-label">Fyzick\xFD</div>
            <div class="bio-stat-value bio-stat-value--physical">${Math.round(t.physical)}%</div>
            <p class="bio-stat-description">${b("physical",t.physical)}</p>
        </div>
        <div class="bio-stat-card">
            <div class="bio-stat-label">Emo\u010Dn\xED</div>
            <div class="bio-stat-value bio-stat-value--emotional">${Math.round(t.emotional)}%</div>
            <p class="bio-stat-description">${b("emotional",t.emotional)}</p>
        </div>
        <div class="bio-stat-card">
            <div class="bio-stat-label">Intelektu\xE1ln\xED</div>
            <div class="bio-stat-value bio-stat-value--intellectual">${Math.round(t.intellectual)}%</div>
            <p class="bio-stat-description">${b("intellectual",t.intellectual)}</p>
        </div>
    `)}document.addEventListener("DOMContentLoaded",()=>{const o=new Date().toISOString().split("T")[0],t=document.getElementById("birthdate");t&&(t.max=o);const e=document.getElementById("biorhythm-form");e&&e.addEventListener("submit",n=>{n.preventDefault();const i=t.value;if(i){const l=document.getElementById("biorhythm-results");l.hidden=!1,l.classList.add("mh-block-visible"),l.scrollIntoView({behavior:"smooth",block:"end"}),m(new Date(i))}}),window.renderBiorhythmChart=m});})();
